package com.example.payment; import java.util.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/payments") public class PaymentController { @PostMapping("/authorize") public Map<String,String> authorize(@RequestBody Map<String,Object> r){if(Boolean.TRUE.equals(r.get("forceFail"))) throw new IllegalStateException("Payment declined"); return Map.of("paymentId",UUID.randomUUID().toString(),"status","AUTHORIZED");} @PostMapping("/refund") public Map<String,String> refund(){return Map.of("status","REFUNDED");} }
